import React, { useState } from "react";
import axios from "../utils/axios";
import EmojiPicker from "emoji-picker-react";
import toast from "react-hot-toast";

const CreateBudgetForm = ({ onSuccess }) => {
  const [emoji, setEmoji] = useState(null);
  const [showPicker, setShowPicker] = useState(false);
  const [budgetName, setBudgetName] = useState("");
  const [budgetAmount, setBudgetAmount] = useState("");
  const [loading, setLoading] = useState(false);

  const today = new Date();
  const currentMonth = today.getMonth() + 1;
  const currentYear = today.getFullYear();

  const handleEmojiClick = (emojiData) => {
    setEmoji(emojiData.emoji);
    setShowPicker(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const userId = localStorage.getItem("userId");
    if (!userId) {
      toast.error("User not logged in");
      return;
    }

    setLoading(true);
    try {
      await axios.post("/api/budgets", {
        icon: emoji,
        name: budgetName,
        amount: parseFloat(budgetAmount),
        month: currentMonth,
        year: currentYear,
        userId: parseInt(userId, 10),
      });

      setBudgetName("");
      setBudgetAmount("");
      setEmoji(null);

      toast.success("Budget created!");
      if (onSuccess) onSuccess();
    } catch (error) {
      console.error("Failed to create budget:", error);
      toast.error(error?.response?.data?.message || "Failed to create budget.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-md w-full max-w-md mx-auto mt-6">
      <h2 className="text-2xl font-bold mb-4 text-gray-800">Create New Budget</h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Select Emoji
          </label>
          <button
            type="button"
            onClick={() => setShowPicker(!showPicker)}
            className="border px-4 py-2 rounded-md text-lg"
          >
            {emoji ? emoji : "Choose Emoji"}
          </button>
          {showPicker && (
            <div className="mt-2 z-10 relative">
              <EmojiPicker onEmojiClick={handleEmojiClick} />
            </div>
          )}
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Budget Name
          </label>
          <input
            type="text"
            value={budgetName}
            onChange={(e) => setBudgetName(e.target.value)}
            required
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            placeholder="e.g., Food, Rent, Travel"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            Budget Amount (RM)
          </label>
          <input
            type="number"
            value={budgetAmount}
            onChange={(e) => setBudgetAmount(e.target.value)}
            required
            min="0"
            step="0.01"
            className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-indigo-500"
            placeholder="e.g., 500"
          />
        </div>

        <div className="pt-2">
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-indigo-600 text-white py-2 px-4 rounded-md hover:bg-indigo-700 transition disabled:opacity-60"
          >
            {loading ? "Creating..." : "Create Budget"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CreateBudgetForm;
